use crate::{job_api::{ConsumerContract,ReportFormat},report_app::{Document,document,read}};
use serde::ser::{Serialize,SerializeMap,Serializer};
use std::{io::Write,path::{Path,PathBuf}};
const RAW_VERSION:&str="f781cef13b5448eaf3673a5d82550d0267086480";
const MQ_CASES:[&str;9]=["export-multiqc-ordinary","export-multiqc-qc-only","export-multiqc-merged","export-multiqc-split","export-multiqc-qualified-required","export-multiqc-wrong-version","export-multiqc-missing-contract","export-multiqc-source-incomplete","export-multiqc-bad-export-extension"];
const API_MQ_CASES:[&str;9]=["export-multiqc-ordinary","export-multiqc-qc-only","export-multiqc-merged","export-multiqc-split","export-multiqc-qualified-required","export-multiqc-wrong-version","export-multiqc-missing-contract","export-multiqc-source-incomplete","api-multiqc-wrong-hash"];
const RAW_CASES:[&str;9]=["export-rawr-se","export-rawr-split-pe","export-rawr-interleaved-pe","export-rawr-quoted-sample-unsupported","export-rawr-missing-metadata","export-rawr-wrong-version","export-rawr-source-qc-only","export-rawr-declared-layout-mismatch","export-rawr-qualified-required"];
pub(crate) fn hash_bytes(bytes:&[u8])->Result<String,String>{let mut c=std::process::Command::new("sha256sum").stdin(std::process::Stdio::piped()).stdout(std::process::Stdio::piped()).spawn().map_err(|e|e.to_string())?;let result=c.stdin.take().unwrap().write_all(bytes);let output=c.wait_with_output().map_err(|e|e.to_string())?;result.map_err(|e|e.to_string())?;if !output.status.success(){return Err("sha256sum failed".into());}let text=std::str::from_utf8(&output.stdout).map_err(|e|e.to_string())?;let hash=text.split_whitespace().next().unwrap_or("");if hash.len()!=64{return Err("invalid content hash".into());}Ok(hash.into())}
fn hash_path(p:&Path)->Result<String,String>{crate::native_screen::sha256(p.to_str().ok_or("non-UTF8 hash path")?)}
fn text(d:&Document<'_>,p:&[&str])->Result<String,String>{d.text(p)?.ok_or_else(||format!("missing consumer metadata {}",p.join(".")))}
fn protect(path:&Path,outputs:&[PathBuf])->Result<(),String>{let path=crate::job_api::path_identity(path)?;if outputs.iter().any(|p|p==&path){Err("consumer/input/output alias".into())}else{Ok(())}}
pub(crate) struct Rawr{sample:String,layout:String,platform:String,paths:Vec<PathBuf>}
pub(crate) struct Named{pub kind:&'static str,pub version:&'static str,pub qualification:String,pub source_sha:String,pub contract_sha:String,rawr:Option<Rawr>}
impl Named{
 pub(crate) fn new(source:&Document<'_>,format:&ReportFormat,contract:&ConsumerContract,source_root:Option<&Path>,outputs:&[PathBuf],producer:&str)->Result<Self,String>{
  let(kind,version)=match format{ReportFormat::Multiqc=>("multiqc-custom-content","1.27.1"),ReportFormat::Mgnify=>("mgnify-rawr-input",RAW_VERSION),_=>return Err("unsupported export format".into())};
  if (contract.name!=kind&&contract.name!=if matches!(format,ReportFormat::Multiqc){"multiqc"}else{"mgnify"})||contract.version!=version{return Err("consumer contract version/name mismatch".into());}protect(&contract.manifest_path,outputs)?;let bytes=read(&contract.manifest_path)?;let contract_sha=hash_bytes(&bytes)?;if contract_sha!=contract.manifest_sha256{return Err("consumer-contract hash mismatch".into());}let c=document(&bytes,&source.working)?;
  if text(&c,&["schema"])?!="soapnuke-v3.consumer-contract/1"||text(&c,&["consumer"])?!=kind||text(&c,&["version"])?!=version||text(&c,&["required_native_status"])?!="complete"{return Err("unsupported consumer-contract schema/version".into());}
  let mut native=false;c.each(&["native_schemas"],|v|{if v.get()=="\"soapnuke-v3.report/2\""{native=true;}Ok(())})?;if !native{return Err("consumer-contract native schema mismatch".into());}
  if source.text(&["status"])?.as_deref()!=Some("complete"){return Err("named exports require complete source report".into());}
  let qualification=text(&c,&["qualification","status"])?;
  if qualification=="draft"{if !contract.allow_unqualified{return Err("draft consumer contract requires allow-unqualified".into());}}else if qualification=="qualified"{Self::verify_receipt(source,&c,kind,version,outputs,producer)?;}else{return Err("unsupported qualification status".into());}
  let source_sha=hash_bytes(source.bytes())?;
  let rawr=if matches!(format,ReportFormat::Mgnify){
   if source.get(&["populations","written"])?.is_none_or(|v|v.get()=="null"){return Err("no written artifacts for QC-only source".into());}
   let binding=c.get(&["input_bindings",&source_sha])?.ok_or("missing hash-bound input metadata binding")?;let b=c.child(binding);
   let sample=text(&b,&["sample"])?;if sample.is_empty()||!sample.bytes().all(|x|x.is_ascii_alphanumeric()||b"_.-".contains(&x)){return Err("workflow sample ID must match [A-Za-z0-9_.-]+".into());}
   let layout=text(&b,&["layout"])?;let platform=text(&b,&["instrument_platform"])?;if !["ILLUMINA","OXFORD_NANOPORE","PACBIO_SMRT","ION_TORRENT","LS454","DNBSEQ","BGISEQ","ULTIMA","COMPLETE_GENOMICS"].contains(&platform.as_str()){return Err("unsupported supplied instrument_platform".into());}
   let mut paths=Vec::with_capacity(2);b.each(&["resolved_paths"],|v|{if paths.len()==2{return Err("too many mate paths".into());}let s=b.child(v).text(&[])?.ok_or("invalid metadata path")?;let p=PathBuf::from(s);let p=if p.is_absolute(){p}else{source_root.ok_or("relative API artifact lacks explicit origin")?.join(p)};let p=std::fs::canonicalize(p).map_err(|e|e.to_string())?;if paths.contains(&p){return Err("mate artifact alias".into());}protect(&p,outputs)?;let s=p.to_str().ok_or("non-UTF8 artifact path")?;if s.chars().any(char::is_whitespace)||!(s.ends_with(".fq.gz")||s.ends_with(".fastq.gz")){return Err("unsupported FASTQ artifact path".into());}paths.push(p);Ok(())})?;
   let native_layout=text(source,&["run","layout"])?;if !matches!((layout.as_str(),paths.len(),native_layout.as_str()),("SE",1,"SE")|("split-PE",2,"PE")|("interleaved-PE",1,"PE")){return Err("declared artifact layout mismatch".into());}
   let mut counts=vec![None;paths.len()];let mut encodings=vec![None;paths.len()];
   source.each(&["outputs"],|v|{let a=source.child(v);let Some(path)=a.text(&["path"])?else{return Ok(())};let p=PathBuf::from(path);let p=if p.is_absolute(){p}else{source_root.ok_or("relative API artifact lacks origin")?.join(p)};let Ok(p)=std::fs::canonicalize(p)else{return Ok(())};if let Some(i)=paths.iter().position(|x|x==&p){if counts[i].is_some(){return Err("duplicate committed artifact".into());}if text(&a,&["state"])?!="committed"||text(&a,&["codec"])?!="gzip"{return Err("uncommitted or non-gzip artifact".into());}let actual=std::fs::metadata(&p).map_err(|e|e.to_string())?.len();if a.number(&["bytes"])?.is_some_and(|n|n!=actual){return Err("artifact byte size mismatch".into());}counts[i]=a.number(&["read_records"])?;encodings[i]=a.number(&["encoding"])?.or(source.number(&["run","output_encoding"])?);}Ok(())})?;
   let counts=counts.into_iter().collect::<Option<Vec<_>>>().ok_or("unbound written artifact")?;let encodings=encodings.into_iter().collect::<Option<Vec<_>>>().ok_or("missing artifact encoding")?;
   crate::source::verify_saved_artifacts(&paths,&encodings,&counts,&layout)?;Some(Rawr{sample,layout,platform,paths})
  }else{let mut found=false;c.each(&["required_consumer_argv"],|v|{if v.get()=="\"--fullnames\""{found=true;}Ok(())})?;if !found{return Err("MultiQC contract requires --fullnames".into());}None};
  Ok(Self{kind,version,qualification,source_sha,contract_sha,rawr})
 }
 fn verify_receipt(source:&Document<'_>,c:&Document<'_>,kind:&str,version:&str,outputs:&[PathBuf],producer:&str)->Result<(),String>{
  let adapter=c.get(&["qualification","production_adapter"])?.ok_or("missing production adapter")?;let a=c.child(adapter);let exe=std::env::current_exe().map_err(|e|e.to_string())?;let identity=hash_path(&exe)?;let manifest=text(&a,&["source_manifest_path"])?;protect(Path::new(&manifest),outputs)?;let source_sha=option_env!("SOAPNUKE_SOURCE_SHA256").ok_or("unbound renderer source identity")?;
  if text(&a,&["binary_sha256"])?!=identity||text(&a,&["source_manifest_sha256"])?!=source_sha||hash_path(Path::new(&manifest))?!=source_sha{return Err("qualified production adapter identity mismatch".into());}
  let path=PathBuf::from(text(c,&["qualification","receipt_path"])?);protect(&path,outputs)?;let bytes=read(&path)?;if hash_bytes(&bytes)?!=text(c,&["qualification","receipt_sha256"])?{return Err("qualification receipt hash mismatch".into());}let r=document(&bytes,&source.working)?;
  let target=if kind=="multiqc-custom-content"{"multiqc"}else{"mgnify"};if text(&r,&["schema"])?!="soapnuke-v3.consumer-compatibility/1"||text(&r,&["status"])?!="qualified"||r.get(&["synthetic"])?.map(|v|v.get())!=Some("false")||text(&r,&["binary_sha256"])?!=identity||text(&r,&["source_manifest_sha256"])?!=source_sha||text(&r,&["target"])?!=target||text(&r,&["consumer_version"])?!=version{return Err("unqualified/mismatched actual consumer receipt".into());}
  let profile=a.text(&["producer_kind"])?.unwrap_or_else(||"cli/1".into());if r.text(&["producer_kind"])?.unwrap_or_else(||"cli/1".into())!=profile||profile!=producer{return Err("consumer producer profile mismatch".into());}
  let required=if target=="multiqc"{if profile=="rust-api/1"{&API_MQ_CASES}else{&MQ_CASES}}else{&RAW_CASES};let mut seen=[false;9];r.each(&["validated_cases"],|v|{let s=r.child(v).text(&[])?.ok_or("invalid case")?;let i=required.iter().position(|x|x==&s).ok_or("unrecognized consumer case")?;if seen[i]{return Err("duplicate consumer case".into());}seen[i]=true;Ok(())})?;if seen.contains(&false)||r.number(&["real_consumer_checks"])?.unwrap_or(0)<if target=="multiqc"{4}else{3}{return Err("incomplete actual consumer coverage".into());}
  let mut argv=0;r.each(&["consumer_argv"],|v|{if target!="multiqc"||v.get()!="\"--fullnames\""{return Err("consumer argv mismatch".into());}argv+=1;Ok(())})?;if argv!=usize::from(target=="multiqc"){return Err("consumer argv mismatch".into());}
  let mut count=0;r.each(&["artifacts"],|v|{let a=r.child(v);let p=PathBuf::from(text(&a,&["path"])?);let p=if p.is_absolute(){p}else{path.parent().unwrap().join(p)};protect(&p,outputs)?;if hash_path(&p)?!=text(&a,&["sha256"])?{return Err("missing/changed consumer artifact".into());}count+=1;Ok(())})?;if count<if target=="multiqc"{8}else{6}{return Err("missing consumer parsed artifacts".into());}Ok(())
 }
 pub(crate) fn write_multiqc<W:Write>(&self,out:&mut W,r:&Document<'_>)->Result<(),String>{
  struct Projection<'a,'b>(&'a Named,&'a Document<'b>);impl Serialize for Projection<'_,'_>{fn serialize<S:Serializer>(&self,s:S)->Result<S::Ok,S::Error>{use serde::ser::Error;let mut m=s.serialize_map(Some(4))?;m.serialize_entry("id","soapnuke_v3")?;m.serialize_entry("plot_type","table")?;
   struct Rows<'a,'b>(&'a Document<'b>);impl Serialize for Rows<'_,'_>{fn serialize<S:Serializer>(&self,s:S)->Result<S::Ok,S::Error>{use serde::ser::Error;let mut m=s.serialize_map(None)?;let sample=text(self.0,&["run","sample_id"]).map_err(S::Error::custom)?;for stage in ["input","accepted","written"]{if self.0.get(&["populations",stage]).map_err(S::Error::custom)?.is_none_or(|v|v.get()=="null"){continue;}let mut metrics=[0u64;4];for(i,key)in ["read_records","bases","q20_bases","q30_bases"].iter().enumerate(){metrics[i]=self.0.number(&["populations",stage,key]).map_err(S::Error::custom)?.ok_or_else(||S::Error::custom("missing numeric metric"))?;}struct Metrics([u64;4]);impl Serialize for Metrics{fn serialize<S:Serializer>(&self,s:S)->Result<S::Ok,S::Error>{let mut m=s.serialize_map(Some(4))?;for(i,k)in ["reads","bases","q20_bases","q30_bases"].iter().enumerate(){m.serialize_entry(k,&self.0[i])?;}m.end()}}m.serialize_entry(&format!("{sample}|{stage}|all"),&Metrics(metrics))?;}m.end()}}
   m.serialize_entry("data",&Rows(self.1))?;let mut unavailable=[None;3];let mut n=0;for stage in ["input","accepted","written"]{if self.1.get(&["populations",stage]).map_err(S::Error::custom)?.is_none_or(|v|v.get()=="null"){unavailable[n]=Some(stage);n+=1;}}
   struct Meta<'a>{named:&'a Named,missing:&'a [Option<&'static str>]}impl Serialize for Meta<'_>{fn serialize<S:Serializer>(&self,s:S)->Result<S::Ok,S::Error>{let mut m=s.serialize_map(Some(5))?;m.serialize_entry("qualification_status",&self.named.qualification)?;m.serialize_entry("source_report_sha256",&self.named.source_sha)?;m.serialize_entry("unavailable_populations",self.missing)?;m.serialize_entry("consumer",self.named.kind)?;m.serialize_entry("consumer_version",self.named.version)?;m.end()}}m.serialize_entry("soapnuke_export",&Meta{named:self.0,missing:&unavailable[..n]})?;m.end()}}
  serde_json::to_writer(out,&Projection(self,r)).map_err(|e|e.to_string())
 }
 pub(crate) fn write_csv<W:Write>(&self,out:&mut W)->Result<(),String>{let r=self.rawr.as_ref().ok_or("not a RawR projection")?;out.write_all(b"sample,fastq_1,fastq_2,single_end,instrument_platform\r\n").map_err(|e|e.to_string())?;let fields=[r.sample.as_str(),r.paths[0].to_str().unwrap(),r.paths.get(1).and_then(|p|p.to_str()).unwrap_or(""),if r.layout=="SE"{"true"}else{"false"},r.platform.as_str()];for(i,field)in fields.iter().enumerate(){if i>0{out.write_all(b",").map_err(|e|e.to_string())?;}let quote=field.contains([',','"','\r','\n']);if quote{out.write_all(b"\"").map_err(|e|e.to_string())?;}for part in field.split_inclusive('"'){out.write_all(part.as_bytes()).map_err(|e|e.to_string())?;if part.ends_with('"'){out.write_all(b"\"").map_err(|e|e.to_string())?;}}if quote{out.write_all(b"\"").map_err(|e|e.to_string())?;}}out.write_all(b"\r\n").map_err(|e|e.to_string())}
 pub(crate) fn write_manifest<W:Write>(&self,out:&mut W,csv:&str)->Result<(),String>{
  struct Meta<'a>(&'a Rawr);impl Serialize for Meta<'_>{fn serialize<S:Serializer>(&self,s:S)->Result<S::Ok,S::Error>{let mut m=s.serialize_map(Some(4))?;m.serialize_entry("sample",&self.0.sample)?;m.serialize_entry("layout",&self.0.layout)?;m.serialize_entry("instrument_platform",&self.0.platform)?;m.serialize_entry("resolved_paths",&self.0.paths)?;m.end()}}
  struct Manifest<'a>(&'a Named,&'a str);impl Serialize for Manifest<'_>{fn serialize<S:Serializer>(&self,s:S)->Result<S::Ok,S::Error>{use serde::ser::Error;let mut m=s.serialize_map(Some(7))?;m.serialize_entry("schema","soapnuke-v3.workflow/1")?;m.serialize_entry("consumer",self.0.kind)?;m.serialize_entry("consumer_version",self.0.version)?;m.serialize_entry("qualification_status",&self.0.qualification)?;m.serialize_entry("native_report_sha256",&self.0.source_sha)?;m.serialize_entry("samplesheet",self.1)?;m.serialize_entry("metadata",&Meta(self.0.rawr.as_ref().ok_or_else(||S::Error::custom("not a RawR projection"))?))?;m.end()}}
  serde_json::to_writer(out,&Manifest(self,csv)).map_err(|e|e.to_string())
 }
}
